fn cgroup_id(cgrp: *const cgroup) -> u64 {
unsafe { (*(*cgrp).kn).id }
}

// task_css_check - obtain css for (task, subsys) w/ extra access conds
// @task: the target task
// @subsys_id: the target subsystem ID
// @__c: extra condition expression to be passed to rcu_dereference_check()
//
// Return the cgroup_subsys_state for the (@task, @subsys_id) pair.  The
// synchronization rules are the same as task_css_set_check().
fn cgroup_is_descendant(cgrp: *mut cgroup, ancestor: *mut cgroup) -> bool {
if (unsafe { (*cgrp).root }) != unsafe { (*ancestor).root } || (unsafe { (*cgrp).level }) < unsafe { (*ancestor).level } {
return false;
}
(unsafe { *(core::ptr::addr_of_mut!((*cgrp).__slate_anon_38.__slate_anon_0.ancestors) as *mut *mut cgroup).wrapping_offset((*ancestor).level as isize) }) == ancestor
}

fn cgroup_ancestor(cgrp: *mut cgroup, ancestor_level: i32) -> *mut cgroup {
if ancestor_level < 0 || ancestor_level > unsafe { (*cgrp).level } {
return core::ptr::null_mut::<cgroup>();
}
unsafe { *(core::ptr::addr_of_mut!((*cgrp).__slate_anon_38.__slate_anon_0.ancestors) as *mut *mut cgroup).wrapping_offset(ancestor_level as isize) }
}

fn sock_cgroup_ptr(skcd: *mut sock_cgroup_data) -> *mut cgroup {
unsafe { (*skcd).cgroup }
}

